//! Cross-language safety tests for the Rust shard implementation.
//!
//! Reads golden safety fixtures generated by the Go `ucodec` package at
//! `../ucodec/testdata/safety/` and verifies that the Rust reader produces
//! identical results, rejects corrupt inputs gracefully (no panics), and
//! roundtrips correctly through the Rust writer.

use serde::Deserialize;
use sha2::{Digest, Sha256};
use shard_format::{ShardV2Reader, ShardV2Writer, ROLE_UNKNOWN};
use std::path::{Path, PathBuf};
use std::sync::Arc;

// ============================================================
// Manifest deserialization structs
// ============================================================

#[derive(Deserialize)]
struct SafetyManifest {
    valid: Vec<ValidFile>,
    corrupt: Vec<CorruptFile>,
}

#[derive(Deserialize)]
struct ValidFile {
    filename: String,
    sha256: String,
    entry_count: usize,
    entries: Vec<ValidEntry>,
}

#[derive(Deserialize)]
struct ValidEntry {
    name: String,
    data_sha256: String,
    size: usize,
}

#[derive(Deserialize)]
struct CorruptFile {
    filename: String,
    expected_error: String,
    description: String,
}

// ============================================================
// Helpers
// ============================================================

fn safety_dir() -> PathBuf {
    let manifest = std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR not set");
    Path::new(&manifest).join("../ucodec/testdata/safety")
}

fn load_safety_manifest() -> SafetyManifest {
    let path = safety_dir().join("safety_manifest.json");
    let contents = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("Failed to read {}: {}", path.display(), e));
    serde_json::from_str(&contents)
        .unwrap_or_else(|e| panic!("Failed to parse safety manifest: {}", e))
}

fn sha256_hex(data: &[u8]) -> String {
    let mut h = Sha256::new();
    h.update(data);
    hex::encode(h.finalize())
}

/// Write entries through ShardV2Writer and return a reader over the result.
/// Uses a temporary file that lives as long as the returned NamedTempFile.
fn write_and_read(
    entries: &[(&str, &[u8])],
) -> (ShardV2Reader, tempfile::NamedTempFile) {
    let mut writer = ShardV2Writer::new(ROLE_UNKNOWN);
    for (name, data) in entries {
        writer.write_entry(name, data);
    }
    let tmp = tempfile::NamedTempFile::new().expect("create tempfile");
    writer
        .write_to_file(tmp.path())
        .expect("write_to_file failed");
    let reader = ShardV2Reader::from_file(tmp.path()).expect("from_file failed");
    (reader, tmp)
}

// ============================================================
// 1. Valid shard tests
// ============================================================

#[test]
fn test_safety_manifest_exists() {
    let path = safety_dir().join("safety_manifest.json");
    assert!(
        path.exists(),
        "safety_manifest.json not found at {}",
        path.display()
    );
}

#[test]
fn test_valid_files_exist() {
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for vf in &manifest.valid {
        let p = dir.join(&vf.filename);
        assert!(
            p.exists(),
            "valid fixture {} not found at {}",
            vf.filename,
            p.display()
        );
    }
}

#[test]
fn test_valid_file_sha256() {
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for vf in &manifest.valid {
        let data = std::fs::read(dir.join(&vf.filename))
            .unwrap_or_else(|e| panic!("read {}: {}", vf.filename, e));
        let got = sha256_hex(&data);
        assert_eq!(
            got, vf.sha256,
            "whole-file SHA256 mismatch for {}",
            vf.filename
        );
    }
}

#[test]
fn test_valid_from_file_succeeds() {
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for vf in &manifest.valid {
        let path = dir.join(&vf.filename);
        let result = ShardV2Reader::from_file(&path);
        assert!(
            result.is_ok(),
            "from_file should succeed for {}: {:?}",
            vf.filename,
            result.err()
        );
    }
}

#[test]
fn test_valid_entry_count() {
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for vf in &manifest.valid {
        let reader = ShardV2Reader::from_file(&dir.join(&vf.filename))
            .unwrap_or_else(|e| panic!("open {}: {}", vf.filename, e));
        assert_eq!(
            reader.entry_count(),
            vf.entry_count,
            "{}: entry_count mismatch",
            vf.filename
        );
    }
}

#[test]
fn test_valid_entry_names() {
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for vf in &manifest.valid {
        let reader = ShardV2Reader::from_file(&dir.join(&vf.filename))
            .unwrap_or_else(|e| panic!("open {}: {}", vf.filename, e));
        let names = reader.entry_names();
        let expected: Vec<&str> = vf.entries.iter().map(|e| e.name.as_str()).collect();
        assert_eq!(
            names, expected,
            "{}: entry names mismatch",
            vf.filename
        );
    }
}

#[test]
fn test_valid_entry_data_sha256() {
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for vf in &manifest.valid {
        let reader = ShardV2Reader::from_file(&dir.join(&vf.filename))
            .unwrap_or_else(|e| panic!("open {}: {}", vf.filename, e));
        for (i, ve) in vf.entries.iter().enumerate() {
            let data = reader.read_entry(i).unwrap_or_else(|e| {
                panic!("{} entry {} ({}): read_entry error: {}", vf.filename, i, ve.name, e)
            });
            assert_eq!(
                data.len(),
                ve.size,
                "{} entry {} ({}): data size mismatch",
                vf.filename,
                i,
                ve.name
            );
            let got = sha256_hex(&data);
            assert_eq!(
                got, ve.data_sha256,
                "{} entry {} ({}): data SHA256 mismatch",
                vf.filename, i, ve.name
            );
        }
    }
}

#[test]
fn test_valid_entry_lookup_by_name() {
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for vf in &manifest.valid {
        let reader = ShardV2Reader::from_file(&dir.join(&vf.filename))
            .unwrap_or_else(|e| panic!("open {}: {}", vf.filename, e));
        for (i, ve) in vf.entries.iter().enumerate() {
            let idx = reader.lookup(&ve.name);
            assert_eq!(
                idx,
                Some(i),
                "{}: lookup({}) returned {:?}, expected Some({})",
                vf.filename,
                ve.name,
                idx,
                i
            );

            // Also verify read_entry_by_name matches read_entry
            let by_name = reader.read_entry_by_name(&ve.name).unwrap_or_else(|e| {
                panic!("{}: read_entry_by_name({}): {}", vf.filename, ve.name, e)
            });
            let by_index = reader.read_entry(i).unwrap_or_else(|e| {
                panic!("{}: read_entry({}): {}", vf.filename, i, e)
            });
            assert_eq!(
                by_name, by_index,
                "{}: read_entry_by_name({}) != read_entry({})",
                vf.filename, ve.name, i
            );
        }
    }
}

