#[test]
fn test_valid_entry_data_size_separate() {
    // Verify data sizes match manifest independently from SHA256 checks.
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for vf in &manifest.valid {
        let reader = ShardV2Reader::from_file(&dir.join(&vf.filename))
            .unwrap_or_else(|e| panic!("open {}: {}", vf.filename, e));
        for (i, ve) in vf.entries.iter().enumerate() {
            let data = reader.read_entry(i).unwrap_or_else(|e| {
                panic!("{} entry {} ({}): read_entry error: {}", vf.filename, i, ve.name, e)
            });
            assert_eq!(
                data.len(),
                ve.size,
                "{} entry {} ({}): size {} != manifest {}",
                vf.filename,
                i,
                ve.name,
                data.len(),
                ve.size
            );
        }
    }
}

#[test]
fn test_valid_lookup_nonexistent() {
    // Verify that lookup("nonexistent") returns None for every valid file.
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    let nonexistent_names = [
        "nonexistent",
        "",
        "does_not_exist",
        "tensor_z",
        "../escape",
        "null\0byte",
    ];
    for vf in &manifest.valid {
        let reader = ShardV2Reader::from_file(&dir.join(&vf.filename))
            .unwrap_or_else(|e| panic!("open {}: {}", vf.filename, e));
        for name in &nonexistent_names {
            assert_eq!(
                reader.lookup(name),
                None,
                "{}: lookup({:?}) should return None",
                vf.filename,
                name
            );
            assert!(
                !reader.has_entry(name),
                "{}: has_entry({:?}) should be false",
                vf.filename,
                name
            );
        }
    }
}

#[test]
fn test_valid_has_entry() {
    // Verify has_entry returns true for all manifest entries, false for garbage.
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for vf in &manifest.valid {
        let reader = ShardV2Reader::from_file(&dir.join(&vf.filename))
            .unwrap_or_else(|e| panic!("open {}: {}", vf.filename, e));
        for ve in &vf.entries {
            assert!(
                reader.has_entry(&ve.name),
                "{}: has_entry({}) should be true",
                vf.filename,
                ve.name
            );
        }
        assert!(
            !reader.has_entry("__definitely_not_here__"),
            "{}: has_entry for garbage name should be false",
            vf.filename
        );
    }
}

#[test]
fn test_valid_read_entry_by_name_error_for_missing() {
    // Verify read_entry_by_name returns Err for names not in the shard.
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for vf in &manifest.valid {
        let reader = ShardV2Reader::from_file(&dir.join(&vf.filename))
            .unwrap_or_else(|e| panic!("open {}: {}", vf.filename, e));
        let result = reader.read_entry_by_name("__does_not_exist__");
        assert!(
            result.is_err(),
            "{}: read_entry_by_name for missing name should return Err",
            vf.filename
        );
    }
}

#[test]
fn test_valid_from_bytes_succeeds() {
    // Verify that from_bytes (in-memory parse) works identically to from_file.
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for vf in &manifest.valid {
        let raw = std::fs::read(dir.join(&vf.filename))
            .unwrap_or_else(|e| panic!("read {}: {}", vf.filename, e));
        let reader = ShardV2Reader::from_bytes(raw)
            .unwrap_or_else(|e| panic!("from_bytes {}: {}", vf.filename, e));
        assert_eq!(
            reader.entry_count(),
            vf.entry_count,
            "{}: from_bytes entry_count mismatch",
            vf.filename
        );
        for (i, ve) in vf.entries.iter().enumerate() {
            let data = reader.read_entry(i).unwrap_or_else(|e| {
                panic!("{} from_bytes entry {} ({}): {}", vf.filename, i, ve.name, e)
            });
            assert_eq!(
                sha256_hex(&data),
                ve.data_sha256,
                "{} from_bytes entry {} ({}): SHA256 mismatch",
                vf.filename,
                i,
                ve.name
            );
        }
    }
}

#[test]
fn test_valid_header_fields() {
    // Spot-check header fields on all valid fixtures.
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for vf in &manifest.valid {
        let reader = ShardV2Reader::from_file(&dir.join(&vf.filename))
            .unwrap_or_else(|e| panic!("open {}: {}", vf.filename, e));
        let hdr = reader.header();
        assert_eq!(
            &hdr.magic, b"SHRD",
            "{}: magic bytes should be SHRD",
            vf.filename
        );
        assert_eq!(
            hdr.version, 0x02,
            "{}: version should be 0x02",
            vf.filename
        );
        assert_eq!(
            hdr.entry_count as usize, vf.entry_count,
            "{}: header entry_count mismatch",
            vf.filename
        );
    }
}

// ============================================================
// 2. Corrupt shard tests
// ============================================================

#[test]
fn test_corrupt_files_exist() {
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for cf in &manifest.corrupt {
        let p = dir.join(&cf.filename);
        assert!(
            p.exists(),
            "corrupt fixture {} not found at {}",
            cf.filename,
            p.display()
        );
    }
}

#[test]
fn test_corrupt_from_file_returns_err() {
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for cf in &manifest.corrupt {
        let path = dir.join(&cf.filename);
        let result = ShardV2Reader::from_file(&path);

        // For most corrupt files, from_file itself should fail.
        // For corrupt_crc_mismatch, from_file may succeed but read_entry must fail.
        match result {
            Err(e) => {
                println!(
                    "OK: {} correctly rejected at open: {} (expected: {}, desc: {})",
                    cf.filename, e, cf.expected_error, cf.description
                );
            }
            Ok(reader) => {
                // File opened but corruption should surface on read_entry.
                // Try reading all entries; at least one must fail.
                let mut any_read_failed = false;
                for i in 0..reader.entry_count() {
                    if reader.read_entry(i).is_err() {
                        any_read_failed = true;
                        break;
                    }
                }
                assert!(
                    any_read_failed,
                    "{}: from_file succeeded AND all read_entry calls succeeded — \
                     corruption was not detected (expected: {}, desc: {})",
                    cf.filename, cf.expected_error, cf.description
                );
                println!(
                    "OK: {} opened but read_entry correctly failed (expected: {}, desc: {})",
                    cf.filename, cf.expected_error, cf.description
                );
            }
        }
    }
}

#[test]
fn test_corrupt_no_panic() {
    // Ensure that no corrupt file causes a panic. We use catch_unwind
    // as an extra safety net on top of the Err-returning API.
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for cf in &manifest.corrupt {
        let path = dir.join(&cf.filename);
        let path_clone = path.clone();
        let result = std::panic::catch_unwind(move || {
            match ShardV2Reader::from_file(&path_clone) {
                Ok(reader) => {
                    for i in 0..reader.entry_count() {
                        let _ = reader.read_entry(i);
                    }
                    let _ = reader.entry_names();
                }
                Err(_) => {}
            }
        });
        assert!(
            result.is_ok(),
            "{}: caused a panic! (desc: {})",
            cf.filename, cf.description
        );
    }
}

#[test]
fn test_corrupt_from_bytes_returns_err() {
    // Verify that from_bytes (in-memory) rejects corrupt data the same as from_file.
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for cf in &manifest.corrupt {
        let raw = std::fs::read(dir.join(&cf.filename))
            .unwrap_or_else(|e| panic!("read {}: {}", cf.filename, e));
        let result = ShardV2Reader::from_bytes(raw);
        match result {
            Err(_) => { /* expected */ }
            Ok(reader) => {
                let mut any_read_failed = false;
                for i in 0..reader.entry_count() {
                    if reader.read_entry(i).is_err() {
                        any_read_failed = true;
                        break;
                    }
                }
                assert!(
                    any_read_failed,
                    "{}: from_bytes succeeded AND all reads passed (expected: {}, desc: {})",
                    cf.filename, cf.expected_error, cf.description
                );
            }
        }
    }
}

#[test]
fn test_corrupt_error_messages_contain_info() {
    // Ensure error messages are descriptive, not just empty strings.
    let manifest = load_safety_manifest();
    let dir = safety_dir();
    for cf in &manifest.corrupt {
        let path = dir.join(&cf.filename);
        let result = ShardV2Reader::from_file(&path);
        match result {
            Err(e) => {
                let msg = format!("{}", e);
                assert!(
                    !msg.is_empty(),
                    "{}: error message should not be empty",
                    cf.filename
                );
                assert!(
                    msg.len() > 5,
                    "{}: error message '{}' is too short to be informative",
                    cf.filename,
                    msg
                );
            }
            Ok(reader) => {
                // For files that open successfully, the error comes from read_entry.
                for i in 0..reader.entry_count() {
                    if let Err(e) = reader.read_entry(i) {
                        let msg = format!("{}", e);
                        assert!(
                            !msg.is_empty(),
                            "{}: read_entry error message should not be empty",
                            cf.filename
                        );
                        assert!(
                            msg.len() > 5,
                            "{}: read_entry error message '{}' is too short",
                            cf.filename,
                            msg
                        );
                        break;
                    }
                }
            }
        }
    }
}

#[test]
fn test_corrupt_empty_file() {
    // A zero-byte file must be rejected.
    let tmp = tempfile::NamedTempFile::new().expect("create tempfile");
    std::fs::write(tmp.path(), b"").expect("write empty file");
    let result = ShardV2Reader::from_file(tmp.path());
    assert!(
        result.is_err(),
        "empty file should be rejected"
    );
}

#[test]
fn test_corrupt_short_magic() {
    // A file with only 3 bytes (incomplete magic) must be rejected.
    let tmp = tempfile::NamedTempFile::new().expect("create tempfile");
    std::fs::write(tmp.path(), b"SHR").expect("write short magic");
    let result = ShardV2Reader::from_file(tmp.path());
    assert!(
        result.is_err(),
        "file with incomplete magic should be rejected"
    );
}

#[test]
fn test_corrupt_wrong_magic() {
    // A 64-byte file with wrong magic must be rejected.
    let tmp = tempfile::NamedTempFile::new().expect("create tempfile");
    let mut data = vec![0u8; 64];
    data[0..4].copy_from_slice(b"NOPE");
    std::fs::write(tmp.path(), &data).expect("write wrong magic");
    let result = ShardV2Reader::from_file(tmp.path());
    assert!(
        result.is_err(),
        "file with wrong magic should be rejected"
    );
}

#[test]
fn test_corrupt_all_zeros() {
    // A file of all zeros must be rejected (magic won't match).
    let tmp = tempfile::NamedTempFile::new().expect("create tempfile");
    std::fs::write(tmp.path(), &vec![0u8; 128]).expect("write zeros");
    let result = ShardV2Reader::from_file(tmp.path());
    assert!(
        result.is_err(),
        "all-zeros file should be rejected"
    );
}

#[test]
fn test_corrupt_random_bytes() {
    // Random-looking bytes should be rejected, not cause panics.
    let data: Vec<u8> = (0..1024).map(|i| ((i * 7 + 13) % 256) as u8).collect();
    let tmp = tempfile::NamedTempFile::new().expect("create tempfile");
    std::fs::write(tmp.path(), &data).expect("write random bytes");
    let result = std::panic::catch_unwind(|| {
        let _ = ShardV2Reader::from_file(tmp.path());
    });
    assert!(
        result.is_ok(),
        "random bytes should not cause a panic"
    );
}

// ============================================================
// 3. Cross-write test (Rust writes, Rust reads back)
// ============================================================

#[test]
fn test_cross_write_roundtrip() {
    let entries: Vec<(&str, Vec<u8>)> = vec![
        ("alpha", [0xDEu8, 0xAD, 0xBE, 0xEF].iter().copied().cycle().take(256).collect()),
        ("beta/weights", (0..256).map(|i| i as u8).collect()),
        ("gamma", vec![0u8; 1024]),
    ];

    // Write using ShardV2Writer
    let mut writer = ShardV2Writer::new(ROLE_UNKNOWN);
    for (name, data) in &entries {
        writer.write_entry(name, data);
    }

    let tmp = tempfile::NamedTempFile::new().expect("create tempfile");
    writer
        .write_to_file(tmp.path())
        .expect("write_to_file failed");

    // Read back
    let reader =
        ShardV2Reader::from_file(tmp.path()).expect("from_file on roundtrip shard failed");

    assert_eq!(reader.entry_count(), entries.len(), "entry count mismatch");

    for (i, (name, data)) in entries.iter().enumerate() {
        assert_eq!(
            reader.entry_name(i),
            *name,
            "entry {} name mismatch",
            i
        );

        let read_data = reader
            .read_entry(i)
            .unwrap_or_else(|e| panic!("read_entry({}) failed: {}", i, e));
        assert_eq!(
            read_data.len(),
            data.len(),
            "entry {} ({}) size mismatch",
            i,
            name
        );

        let expected_hash = sha256_hex(data);
        let got_hash = sha256_hex(&read_data);
        assert_eq!(
            got_hash, expected_hash,
            "entry {} ({}) SHA256 mismatch",
            i, name
        );
    }
}

#[test]
fn test_cross_write_by_name_lookup() {
    let mut writer = ShardV2Writer::new(ROLE_UNKNOWN);
    writer.write_entry("foo", b"hello");
    writer.write_entry("bar/baz", b"world");
    writer.write_entry("qux", b"!");

    let tmp = tempfile::NamedTempFile::new().expect("create tempfile");
    writer
        .write_to_file(tmp.path())
        .expect("write_to_file failed");

    let reader = ShardV2Reader::from_file(tmp.path()).expect("from_file failed");

    assert_eq!(reader.lookup("foo"), Some(0));
    assert_eq!(reader.lookup("bar/baz"), Some(1));
    assert_eq!(reader.lookup("qux"), Some(2));
    assert_eq!(reader.lookup("nonexistent"), None);

    let data = reader.read_entry_by_name("bar/baz").expect("read bar/baz");
    assert_eq!(data, b"world");
}

#[test]
fn test_cross_write_empty_entry() {
    // Write an entry with zero-length data, read back and verify.
    let (reader, _tmp) = write_and_read(&[("empty_entry", &[])]);

    assert_eq!(reader.entry_count(), 1, "should have 1 entry");
    assert_eq!(reader.entry_name(0), "empty_entry");

    let data = reader.read_entry(0).expect("read empty entry");
    assert_eq!(data.len(), 0, "empty entry should have 0 bytes");
    assert_eq!(
        sha256_hex(&data),
        "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
        "SHA256 of empty data should match known hash"
    );
}

#[test]
fn test_cross_write_unicode_names() {
    // Write entries with Unicode names (emoji, CJK, Arabic, Cyrillic), read back.
    let entries: Vec<(&str, &[u8])> = vec![
        ("\u{65e5}\u{672c}\u{8a9e}", b"nihongo" as &[u8]),       // Japanese
        ("emoji_\u{1f600}_face", b"grinning"),                    // emoji
        ("\u{0627}\u{0644}\u{0639}\u{0631}\u{0628}\u{064a}\u{0629}", b"arabic"), // Arabic
        ("\u{0410}\u{0411}\u{0412}\u{0413}", b"cyrillic"),        // Cyrillic
        ("mixed/\u{4e2d}\u{6587}/path", b"chinese_path"),         // CJK in path
    ];

    let (reader, _tmp) = write_and_read(&entries);

    assert_eq!(reader.entry_count(), entries.len(), "entry count mismatch");

    for (i, (name, data)) in entries.iter().enumerate() {
        assert_eq!(
            reader.entry_name(i), *name,
            "entry {} unicode name mismatch",
            i
        );
        let read_data = reader.read_entry(i).unwrap_or_else(|e| {
            panic!("entry {} ({}): read error: {}", i, name, e)
        });
        assert_eq!(
            read_data, *data,
            "entry {} ({}) data mismatch",
            i, name
        );
        // Verify lookup by unicode name works
        assert_eq!(
            reader.lookup(name), Some(i),
            "lookup({}) should return Some({})",
            name, i
        );
    }
}

#[test]
fn test_cross_write_large_entry() {
    // Write a 1 MB+ entry, verify SHA256 integrity on round-trip.
    let size = 1_048_576 + 1337; // 1 MB + 1337 bytes
    let large_data: Vec<u8> = (0..size).map(|i| (i % 251) as u8).collect();
    let expected_sha = sha256_hex(&large_data);

    let mut writer = ShardV2Writer::new(ROLE_UNKNOWN);
    writer.write_entry("large_tensor", &large_data);

    let tmp = tempfile::NamedTempFile::new().expect("create tempfile");
    writer
        .write_to_file(tmp.path())
        .expect("write_to_file failed");

    let reader = ShardV2Reader::from_file(tmp.path()).expect("from_file failed");
    assert_eq!(reader.entry_count(), 1);
    assert_eq!(reader.entry_name(0), "large_tensor");

    let read_data = reader.read_entry(0).expect("read large entry");
    assert_eq!(read_data.len(), size, "large entry size mismatch");
    assert_eq!(
        sha256_hex(&read_data),
        expected_sha,
        "large entry SHA256 mismatch"
    );
}

#[test]
fn test_cross_write_many_entries() {
    // Write 200 entries, verify all round-trip correctly.
    let count = 200;
    let entries: Vec<(String, Vec<u8>)> = (0..count)
        .map(|i| {
            let name = format!("layer_{:04}/weights", i);
            // Each entry has unique data seeded by its index.
            let data: Vec<u8> = (0..128).map(|j| ((i * 7 + j * 13) % 256) as u8).collect();
            (name, data)
        })
        .collect();

    let mut writer = ShardV2Writer::new(ROLE_UNKNOWN);
    for (name, data) in &entries {
        writer.write_entry(name, data);
    }

    let tmp = tempfile::NamedTempFile::new().expect("create tempfile");
    writer
        .write_to_file(tmp.path())
        .expect("write_to_file failed");

    let reader = ShardV2Reader::from_file(tmp.path()).expect("from_file failed");
    assert_eq!(reader.entry_count(), count, "entry count mismatch for many entries");

    for (i, (name, data)) in entries.iter().enumerate() {
        assert_eq!(
            reader.entry_name(i), name.as_str(),
            "entry {} name mismatch",
            i
        );
        let read_data = reader.read_entry(i).unwrap_or_else(|e| {
            panic!("entry {} ({}): read error: {}", i, name, e)
        });
        assert_eq!(
            sha256_hex(&read_data),
            sha256_hex(data),
            "entry {} ({}) SHA256 mismatch",
            i,
            name
        );
    }

    // Verify name lookups work for a sampling of entries.
    for i in [0, 50, 99, 150, 199] {
        let name = &entries[i].0;
        assert_eq!(
            reader.lookup(name.as_str()),
            Some(i),
            "lookup({}) failed",
            name
        );
    }
}

#[test]
fn test_cross_write_binary_data_all_byte_values() {
    // Write all 256 byte values and verify exact content on read-back.
    let all_bytes: Vec<u8> = (0..=255u8).collect();
    let expected_sha = sha256_hex(&all_bytes);

    let (reader, _tmp) = write_and_read(&[("all_bytes", &all_bytes)]);

    let data = reader.read_entry(0).expect("read all_bytes");
    assert_eq!(data.len(), 256);
    assert_eq!(sha256_hex(&data), expected_sha);
    for i in 0..256 {
        assert_eq!(
            data[i], i as u8,
            "byte {} mismatch: got {}, expected {}",
            i, data[i], i
        );
    }
}

#[test]
fn test_cross_write_crc_integrity() {
    // Write a shard, read it back to confirm CRC passes, then corrupt a data
    // byte in the file and verify that the reader detects the corruption.
    let original_data = b"integrity check payload with enough bytes to matter";

    let mut writer = ShardV2Writer::new(ROLE_UNKNOWN);
    writer.write_entry("crc_test", original_data);

    let tmp = tempfile::NamedTempFile::new().expect("create tempfile");
    writer
        .write_to_file(tmp.path())
        .expect("write_to_file failed");

    // First, verify the shard reads cleanly.
    {
        let reader = ShardV2Reader::from_file(tmp.path()).expect("from_file failed");
        let data = reader.read_entry(0).expect("initial read should succeed");
        assert_eq!(data, original_data, "initial data mismatch");
    }

    // Now corrupt a byte in the data section. The data section is after the
    // header + index + string table, so we corrupt near the end of the file
    // (but before the last byte to avoid total_file_size mismatch).
    {
        let mut file_bytes = std::fs::read(tmp.path()).expect("read shard file");
        let corrupt_pos = file_bytes.len() - 10;
        file_bytes[corrupt_pos] ^= 0xFF; // flip all bits of one byte
        std::fs::write(tmp.path(), &file_bytes).expect("write corrupted shard");
    }

    // Read the corrupted file — it should either fail to open or fail on read_entry.
    let result = ShardV2Reader::from_file(tmp.path());
    match result {
        Err(_) => {
            // Corruption detected at open time — acceptable.
        }
        Ok(reader) => {
            let read_result = reader.read_entry(0);
            assert!(
                read_result.is_err(),
                "reading corrupted entry should fail (CRC mismatch)"
            );
        }
    }
}

#[test]
fn test_cross_write_single_byte_entry() {
    // Edge case: a single-byte entry.
    let (reader, _tmp) = write_and_read(&[("one", &[0x42])]);
    let data = reader.read_entry(0).expect("read single byte");
    assert_eq!(data, &[0x42]);
}

#[test]
fn test_cross_write_duplicate_like_names() {
    // Entries with similar but distinct names should not collide.
    let entries: Vec<(&str, &[u8])> = vec![
        ("a", b"first" as &[u8]),
        ("aa", b"second"),
        ("a/a", b"third"),
        ("a/b", b"fourth"),
    ];
    let (reader, _tmp) = write_and_read(&entries);

    assert_eq!(reader.entry_count(), 4);
    for (i, (name, data)) in entries.iter().enumerate() {
        assert_eq!(reader.entry_name(i), *name);
        let read = reader.read_entry(i).expect("read entry");
        assert_eq!(read, *data, "entry {} ({}) data mismatch", i, name);
        assert_eq!(reader.lookup(name), Some(i));
    }
}

#[test]
fn test_cross_write_to_bytes_matches_to_file() {
    // Verify that to_bytes() produces identical output to write_to_file().
    let mut writer = ShardV2Writer::new(ROLE_UNKNOWN);
    writer.write_entry("x", b"data_x");
    writer.write_entry("y", b"data_y");

    let in_memory = writer.to_bytes();

    let tmp = tempfile::NamedTempFile::new().expect("create tempfile");
    writer
        .write_to_file(tmp.path())
        .expect("write_to_file failed");
    let on_disk = std::fs::read(tmp.path()).expect("read file");

    assert_eq!(in_memory, on_disk, "to_bytes() and write_to_file() should produce identical output");

    // Both should be readable.
    let reader = ShardV2Reader::from_bytes(in_memory).expect("from_bytes");
    assert_eq!(reader.entry_count(), 2);
    assert_eq!(
        reader.read_entry(0).expect("read x"),
        b"data_x"
    );
    assert_eq!(
        reader.read_entry(1).expect("read y"),
        b"data_y"
    );
}

