#[test]
fn test_concurrent_reads() {
    let dir = safety_dir();
    let path = dir.join("valid_basic.shard");
    let reader = Arc::new(
        ShardV2Reader::from_file(&path).expect("open valid_basic.shard for concurrent test"),
    );

    let num_threads = 10;
    let mut handles = Vec::with_capacity(num_threads);

    for thread_id in 0..num_threads {
        let reader_clone = Arc::clone(&reader);
        handles.push(std::thread::spawn(move || {
            // Each thread reads all entries and verifies SHA256 against the
            // manifest values (hardcoded from valid_basic.shard).
            let expected_hashes = [
                ("tensor_a", "477e0dc549fdaf0f7a6e00a1c693454096d0aecbc6610ec820b377e70e712b17"),
                ("tensor_b", "347e635d9369f762d476eee696313d7073a0536d89f2dfe1c0c5712b1a719ed1"),
                ("tensor_c", "2034f7bb7a3a79f0b9651811aafd266b605c6d4c817c3fc4ce94e367dff216d8"),
            ];

            assert_eq!(
                reader_clone.entry_count(),
                expected_hashes.len(),
                "thread {}: entry count mismatch",
                thread_id
            );

            for (i, (expected_name, expected_sha)) in expected_hashes.iter().enumerate() {
                let name = reader_clone.entry_name(i);
                assert_eq!(
                    name, *expected_name,
                    "thread {} entry {}: name mismatch",
                    thread_id, i
                );

                let data = reader_clone
                    .read_entry(i)
                    .unwrap_or_else(|e| {
                        panic!("thread {} entry {}: read_entry error: {}", thread_id, i, e)
                    });

                let got = sha256_hex(&data);
                assert_eq!(
                    got, *expected_sha,
                    "thread {} entry {} ({}): SHA256 mismatch",
                    thread_id, i, expected_name
                );
            }
        }));
    }

    for (i, handle) in handles.into_iter().enumerate() {
        handle
            .join()
            .unwrap_or_else(|e| panic!("thread {} panicked: {:?}", i, e));
    }
}

#[test]
fn test_concurrent_reads_all_valid() {
    // Test concurrent reads on ALL valid fixtures, not just valid_basic.
    let manifest = load_safety_manifest();
    let dir = safety_dir();

    for vf in &manifest.valid {
        let path = dir.join(&vf.filename);
        let reader = Arc::new(
            ShardV2Reader::from_file(&path)
                .unwrap_or_else(|e| panic!("open {}: {}", vf.filename, e)),
        );

        // Build expected SHA256 map from manifest.
        let expected: Vec<(String, String)> = vf
            .entries
            .iter()
            .map(|e| (e.name.clone(), e.data_sha256.clone()))
            .collect();
        let expected = Arc::new(expected);

        let num_threads = 4;
        let mut handles = Vec::with_capacity(num_threads);

        for thread_id in 0..num_threads {
            let reader_c = Arc::clone(&reader);
            let expected_c = Arc::clone(&expected);
            let filename = vf.filename.clone();

            handles.push(std::thread::spawn(move || {
                assert_eq!(
                    reader_c.entry_count(),
                    expected_c.len(),
                    "thread {} {}: entry count mismatch",
                    thread_id,
                    filename
                );

                for (i, (expected_name, expected_sha)) in expected_c.iter().enumerate() {
                    let name = reader_c.entry_name(i);
                    assert_eq!(
                        name, expected_name.as_str(),
                        "thread {} {} entry {}: name mismatch",
                        thread_id, filename, i
                    );

                    let data = reader_c.read_entry(i).unwrap_or_else(|e| {
                        panic!(
                            "thread {} {} entry {} ({}): {}",
                            thread_id, filename, i, expected_name, e
                        )
                    });

                    let got = sha256_hex(&data);
                    assert_eq!(
                        got,
                        expected_sha.as_str(),
                        "thread {} {} entry {} ({}): SHA256 mismatch",
                        thread_id,
                        filename,
                        i,
                        expected_name
                    );
                }
            }));
        }

        for (i, handle) in handles.into_iter().enumerate() {
            handle.join().unwrap_or_else(|e| {
                panic!(
                    "thread {} panicked on {}: {:?}",
                    i, vf.filename, e
                )
            });
        }
    }
}

#[test]
fn test_concurrent_reads_stress() {
    // 50 threads, each reading all entries 5 times — stress test for data races.
    let dir = safety_dir();
    let path = dir.join("valid_basic.shard");
    let reader = Arc::new(
        ShardV2Reader::from_file(&path).expect("open valid_basic.shard for stress test"),
    );

    let manifest = load_safety_manifest();
    let vf = &manifest.valid[0]; // valid_basic.shard
    let expected: Vec<(String, String, usize)> = vf
        .entries
        .iter()
        .map(|e| (e.name.clone(), e.data_sha256.clone(), e.size))
        .collect();
    let expected = Arc::new(expected);

    let num_threads = 50;
    let iterations_per_thread = 5;
    let mut handles = Vec::with_capacity(num_threads);

    for thread_id in 0..num_threads {
        let reader_c = Arc::clone(&reader);
        let expected_c = Arc::clone(&expected);

        handles.push(std::thread::spawn(move || {
            for iter in 0..iterations_per_thread {
                for (i, (expected_name, expected_sha, expected_size)) in
                    expected_c.iter().enumerate()
                {
                    let name = reader_c.entry_name(i);
                    assert_eq!(
                        name, expected_name.as_str(),
                        "thread {} iter {} entry {}: name mismatch",
                        thread_id, iter, i
                    );

                    let data = reader_c.read_entry(i).unwrap_or_else(|e| {
                        panic!(
                            "thread {} iter {} entry {} ({}): {}",
                            thread_id, iter, i, expected_name, e
                        )
                    });

                    assert_eq!(
                        data.len(),
                        *expected_size,
                        "thread {} iter {} entry {} ({}): size mismatch",
                        thread_id,
                        iter,
                        i,
                        expected_name
                    );

                    let got = sha256_hex(&data);
                    assert_eq!(
                        got,
                        expected_sha.as_str(),
                        "thread {} iter {} entry {} ({}): SHA256 mismatch",
                        thread_id,
                        iter,
                        i,
                        expected_name
                    );
                }
            }
        }));
    }

    for (i, handle) in handles.into_iter().enumerate() {
        handle
            .join()
            .unwrap_or_else(|e| panic!("stress thread {} panicked: {:?}", i, e));
    }
}

#[test]
fn test_concurrent_reads_with_lookups() {
    // Concurrent threads performing interleaved read_entry and lookup operations.
    let dir = safety_dir();
    let path = dir.join("valid_basic.shard");
    let reader = Arc::new(
        ShardV2Reader::from_file(&path).expect("open valid_basic.shard for lookup concurrency"),
    );

    let num_threads = 20;
    let mut handles = Vec::with_capacity(num_threads);

    for thread_id in 0..num_threads {
        let reader_c = Arc::clone(&reader);
        handles.push(std::thread::spawn(move || {
            // Alternate between lookup and read_entry_by_name.
            let names = ["tensor_a", "tensor_b", "tensor_c"];
            for round in 0..3 {
                for (i, name) in names.iter().enumerate() {
                    let idx = reader_c.lookup(name);
                    assert_eq!(
                        idx,
                        Some(i),
                        "thread {} round {} lookup({}): got {:?}",
                        thread_id,
                        round,
                        name,
                        idx
                    );
                    let by_name = reader_c
                        .read_entry_by_name(name)
                        .unwrap_or_else(|e| {
                            panic!(
                                "thread {} round {} read_entry_by_name({}): {}",
                                thread_id, round, name, e
                            )
                        });
                    let by_index = reader_c.read_entry(i).unwrap_or_else(|e| {
                        panic!(
                            "thread {} round {} read_entry({}): {}",
                            thread_id, round, i, e
                        )
                    });
                    assert_eq!(
                        by_name, by_index,
                        "thread {} round {}: by_name({}) != by_index({})",
                        thread_id, round, name, i
                    );
                }
                // Also verify nonexistent lookup doesn't crash under concurrency.
                assert_eq!(
                    reader_c.lookup("nonexistent"),
                    None,
                    "thread {} round {}: nonexistent lookup should be None",
                    thread_id,
                    round
                );
            }
        }));
    }

    for (i, handle) in handles.into_iter().enumerate() {
        handle
            .join()
            .unwrap_or_else(|e| panic!("lookup thread {} panicked: {:?}", i, e));
    }
}

