#[test]
fn test_cross_write_entry_names_with_special_chars() {
    // Names with dots, dashes, underscores, and deep nesting.
    let entries: Vec<(&str, &[u8])> = vec![
        ("layer.0.weight", b"w0" as &[u8]),
        ("layer-1-bias", b"b1"),
        ("a/b/c/d/e/f", b"deep"),
        ("name_with_underscores", b"u"),
        ("123numeric", b"n"),
    ];
    let (reader, _tmp) = write_and_read(&entries);

    assert_eq!(reader.entry_count(), entries.len());
    for (i, (name, data)) in entries.iter().enumerate() {
        assert_eq!(reader.entry_name(i), *name);
        assert_eq!(reader.lookup(name), Some(i));
        let read = reader.read_entry(i).expect("read entry");
        assert_eq!(read, *data);
    }
}

#[test]
fn test_cross_write_exact_power_of_two_sizes() {
    // Test entries at exact power-of-two boundaries (alignment edge cases).
    for &size in &[1usize, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 4096] {
        let data: Vec<u8> = (0..size).map(|i| (i % 256) as u8).collect();
        let name = format!("pow2_{}", size);

        let (reader, _tmp) = write_and_read(&[(&name, &data)]);
        let read = reader.read_entry(0).unwrap_or_else(|e| {
            panic!("size {}: read error: {}", size, e)
        });
        assert_eq!(
            read.len(),
            size,
            "size {}: length mismatch",
            size
        );
        assert_eq!(
            sha256_hex(&read),
            sha256_hex(&data),
            "size {}: SHA256 mismatch",
            size
        );
    }
}

#[test]
fn test_cross_write_preserves_entry_order() {
    // Verify that entry order is preserved exactly as written.
    let names: Vec<String> = (0..20)
        .map(|i| format!("entry_{:02}", 19 - i)) // reverse order
        .collect();
    let entries: Vec<(&str, &[u8])> = names
        .iter()
        .map(|n| (n.as_str(), b"data" as &[u8]))
        .collect();

    let (reader, _tmp) = write_and_read(&entries);

    let read_names = reader.entry_names();
    let expected_names: Vec<&str> = names.iter().map(|s| s.as_str()).collect();
    assert_eq!(
        read_names, expected_names,
        "entry order must be preserved"
    );
}

#[test]
fn test_cross_write_list_prefix() {
    // Verify list_prefix returns correct entries.
    let entries: Vec<(&str, &[u8])> = vec![
        ("model/layer0/weight", b"w0" as &[u8]),
        ("model/layer0/bias", b"b0"),
        ("model/layer1/weight", b"w1"),
        ("config", b"cfg"),
    ];
    let (reader, _tmp) = write_and_read(&entries);

    let model_entries = reader.list_prefix("model");
    assert_eq!(model_entries.len(), 3, "model/ prefix should match 3 entries");
    for name in &model_entries {
        assert!(
            name.starts_with("model/"),
            "list_prefix result '{}' should start with 'model/'",
            name
        );
    }

    let layer0_entries = reader.list_prefix("model/layer0");
    assert_eq!(layer0_entries.len(), 2, "model/layer0/ prefix should match 2 entries");

    let config_entries = reader.list_prefix("config");
    assert_eq!(config_entries.len(), 1, "config prefix should match 1 entry");

    let none_entries = reader.list_prefix("nonexistent");
    assert!(none_entries.is_empty(), "nonexistent prefix should match 0 entries");
}

#[test]
fn test_cross_write_list_children() {
    // Verify list_children returns immediate children only.
    let entries: Vec<(&str, &[u8])> = vec![
        ("a/b/c", b"abc" as &[u8]),
        ("a/b/d", b"abd"),
        ("a/e", b"ae"),
        ("f", b"f"),
    ];
    let (reader, _tmp) = write_and_read(&entries);

    let root_children = reader.list_children("");
    // Should have: "a/", "f"
    assert!(
        root_children.contains(&"a/".to_string()),
        "root children should contain 'a/'"
    );
    assert!(
        root_children.contains(&"f".to_string()),
        "root children should contain 'f'"
    );
    assert_eq!(root_children.len(), 2, "root should have 2 children");

    let a_children = reader.list_children("a/");
    // Should have: "a/b/", "a/e"
    assert!(
        a_children.contains(&"a/b/".to_string()),
        "a/ children should contain 'a/b/'"
    );
    assert!(
        a_children.contains(&"a/e".to_string()),
        "a/ children should contain 'a/e'"
    );
    assert_eq!(a_children.len(), 2, "a/ should have 2 children");
}
